   109	/**
   110	 * Normalize source value to canonical key
   111	 * Maps legacy/variant names to canonical keys
   112	 */
   113	const SOURCE_ALIAS_MAP = {
   114	  // Legacy variations
   115	  'malmolive': 'malmo-live',
   116	  'stockholmlive': 'malmo-live',
   117	};
