   119	/**
   120	 * Get canonical source key
   121	 * @param {string} source - Source value from event
   122	 * @returns {string} Canonical source key
   123	 */
   124	function normalizeSource(source) {
   125	  if (!source) return 'unknown';
   126	  const normalized = source.toLowerCase().trim();
   127	  return SOURCE_ALIAS_MAP[normalized] || normalized;
   128	}
