   130	/**
   131	 * Get source metadata for frontend dropdown
   132	 * @returns {Array} Array of { key, label, type } objects
   133	 */
   134	function getSourcesMetadata() {
   135	  return Object.entries(CANONICAL_SOURCES).map(([key, meta]) => ({
   136	    key,
   137	    label: meta.label,
   138	    type: meta.type,
   139	  }));
   140	}
