   142	/**
   143	 * Normalize event source to canonical key
   144	 * @param {Object} event - Event object
   145	 * @returns {Object} Event with normalized source
   146	 */
   147	function normalizeEvent(event) {
   148	  return {
   149	    ...event,
   150	    source: normalizeSource(event.source),
   151	  };
