   157	async function fetchTicketmasterEvents(city = 'Stockholm', countryCode = 'SE', size = 50) {
   158	  const url = `https://app.ticketmaster.com/discovery/v2/events.json?apikey=${TICKETMASTER_API_KEY}&city=${city}&countryCode=${countryCode}&size=${size}&sort=date,asc`;
   159	  
   160	  console.log(`[api] Fetching Ticketmaster events for ${city}...`);
   161	  
   162	  try {
   163	    const response = await axios.get(url, { timeout: 15000 });
   164	    
   165	    if (response.status !== 200) {
   166	      console.log(`[api] Ticketmaster returned ${response.status}`);
   167	      return { error: `HTTP ${response.status}`, events: [] };
   168	    }
   169	    
   170	    const data = response.data;
   171	    
   172	    if (!data._embedded || !data._embedded.events) {
   173	      console.log(`[api] No events found`);
   174	      return { events: [], count: 0 };
   175	    }
   176	    
   177	    const events = data._embedded.events.map(ev => ({
   178	      id: ev.id,
   179	      title: ev.name,
   180	      date: ev.dates?.start?.localDate || '',
   181	      time: ev.dates?.start?.localTime ? ev.dates.start.localTime.substring(0, 5) : '',
   182	      venue: ev._embedded?.venues?.[0]?.name || 'Unknown',
   183	      area: ev._embedded?.venues?.[0]?.city?.name || city,
   184	      description: ev.info || ev.pleaseNote || '',
   185	      url: ev.url || '',
   186	      source: 'ticketmaster',
   187	      imageUrl: ev.images?.[0]?.url || null,
   188	      priceRanges: ev.priceRanges || [],
   189	    }));
   190	    
   191	    console.log(`[api] Ticketmaster: ${events.length} events`);
   192	    return { events, count: events.length };
   193	  } catch (error) {
   194	    console.error(`[api] Ticketmaster error: ${error.message}`);
   195	    return { error: error.message, events: [] };
   196	  }
   197	}
