   209	      {
   210	        size: 20,
   211	        query: { bool: { must: [{ range: { tixStartDate: { gte: 'now' } } }] } },
   212	        sort: [{ tixStartDate: { order: 'asc' } }],
   213	      },
   214	      { timeout: 10000, headers: { 'Content-Type': 'application/json' } }
   215	    );
   216	    
   217	    if (esResp.data?.hits?.hits) {
   218	      results.sources.kulturhuset = esResp.data.hits.hits.map(h => ({
   219	        id: h._id,
   220	        title: h._source?.drupalTitle || h._source?.tixName || 'Untitled',
   221	        date: (h._source?.tixStartDate || '').split('T')[0],
   222	        source: 'kulturhuset',
   223	      }));
   224	    }
   225	  } catch (e) {
   226	    console.log(`[api] Kulturhuset: ${e.message}`);
