   231	    const malmoResp = await axios.get('https://malmolive.se/api/events', { timeout: 10000 });
   232	    if (Array.isArray(malmoResp.data)) {
   233	      results.sources.malmolive = malmoResp.data.slice(0, 20).map(e => ({
   234	        id: e.tessitura_event_id || e.id,
   235	        title: e.title || e.name || 'Untitled',
   236	        date: (e.field_date_time || '').split('T')[0],
   237	        source: 'malmolive',
   238	      }));
   239	    }
   240	  } catch (e) {
   241	    console.log(`[api] Malmö Live: ${e.message}`);
   242	  }
   243	  
   244	  return results;
