   250	async function handleEvents(req, res) {
   251	  const url = new URL(req.url, `http://localhost:${PORT}`);
   252	  const city = url.searchParams.get('city') || 'Stockholm';
   253	  const size = parseInt(url.searchParams.get('size') || '50');
   254	  
   255	  const ticketmaster = await fetchTicketmasterEvents(city, 'SE', size);
   256	  const otherSources = await fetchOtherSources();
   257	  
   258	  // Normalize all event sources to canonical keys
   259	  const normalizedTicketmaster = {
   260	    ...ticketmaster,
   261	    events: ticketmaster.events.map(normalizeEvent),
   262	  };
   263	  
   264	  const normalizedOtherSources = {
   265	    sources: {},
   266	  };
   267	  
   268	  // Normalize Kulturhuset events
   269	  if (otherSources.sources.kulturhuset) {
   270	    normalizedOtherSources.sources.kulturhuset = otherSources.sources.kulturhuset.map(normalizeEvent);
   271	  }
   272	  
   273	  // Normalize Malmö Live events (will become 'malmo-live' after normalization)
   274	  if (otherSources.sources.malmolive) {
   275	    normalizedOtherSources.sources.malmolive = otherSources.sources.malmolive.map(normalizeEvent);
   276	  }
   277	  
   278	  // Collect all available sources (for frontend dropdown)
   279	  const availableSources = new Set();
   280	  normalizedTicketmaster.events.forEach(e => availableSources.add(e.source));
   281	  Object.values(normalizedOtherSources.sources).forEach(events => {
   282	    events.forEach(e => availableSources.add(e.source));
   283	  });
   284	  
   285	  // Build sources metadata for dropdown (only include sources that have events)
   286	  const sources = getSourcesMetadata().filter(s => availableSources.has(s.key));
   287	  
   288	  const response = {
   289	    timestamp: new Date().toISOString(),
   290	    ticketmaster: normalizedTicketmaster,
   291	    otherSources: normalizedOtherSources,
   292	    sources: sources,
   293	    totalEvents: ticketmaster.count + 
   294	      (otherSources.sources.kulturhuset?.length || 0) +
   295	      (otherSources.sources.malmolive?.length || 0),
   296	  };
   297	  
   298	  res.writeHead(200, { 
   299	    'Content-Type': 'application/json',
   300	    'Access-Control-Allow-Origin': '*',
   301	  });
   302	  res.end(JSON.stringify(response, null, 2));
   303	}
