   318	/**
   319	 * Fetch events from Supabase (normalized and stored events)
   320	 */
   321	async function handleSupabaseEvents(req, res) {
   322	  if (!supabase) {
   323	    res.writeHead(503, { 'Content-Type': 'application/json' });
   324	    res.end(JSON.stringify({ error: 'Supabase not configured' }));
   325	    return;
   326	  }
   327	
   328	  const url = new URL(req.url, `http://localhost:${PORT}`);
   329	  const city = url.searchParams.get('city') || 'Stockholm';
   330	  const days = parseInt(url.searchParams.get('days') || '365');
   331	  const limit = parseInt(url.searchParams.get('limit') || '100');
   332	  const source = url.searchParams.get('source') || null;
   333	
   334	  try {
   335	    // Calculate date range
   336	    const now = new Date();
   337	    const startDate = now.toISOString();
   338	    const endDate = new Date(now.getTime() + days * 24 * 60 * 60 * 1000).toISOString();
   339	
   340	    // Build query
   341	    let query = supabase
   342	      .from('events')
   343	      .select(`
   344	        id,
   345	        title_en,
   346	        title_sv,
   347	        description_en,
   348	        description_sv,
   349	        start_time,
   350	        end_time,
   351	        source,
   352	        venue_id,
   353	        venues:venue_id(name, address),
   354	        category_slug,
   355	        is_free,
   356	        price_min_sek,
   357	        price_max_sek,
   358	        ticket_url,
   359	        image_url
   360	      `)
   361	      .gte('start_time', startDate)
   362	      .lte('start_time', endDate)
   363	      .eq('status', 'published')
   364	      .order('start_time', { ascending: true })
   365	      .limit(limit);
   366	
   367	    // Filter by source if specified
   368	    if (source) {
   369	      query = query.eq('source', source);
   370	    }
   371	
   372	    const { data: events, error } = await query;
   373	
   374	    if (error) {
   375	      console.error('[api] Supabase query error:', error);
   376	      res.writeHead(500, { 'Content-Type': 'application/json' });
   377	      res.end(JSON.stringify({ error: error.message }));
   378	      return;
   379	    }
   380	
   381	    // Transform to frontend format
   382	    const transformedEvents = (events || []).map(ev => ({
   383	      id: ev.id,
   384	      title: ev.title_en || ev.title_sv || 'Untitled',
   385	      date: ev.start_time ? ev.start_time.split('T')[0] : '',
   386	      time: ev.start_time ? ev.start_time.split('T')[1]?.substring(0, 5) : '',
   387	      venue: ev.venues?.name || '',
   388	      area: city,
   389	      description: ev.description_en || ev.description_sv || '',
   390	      url: ev.ticket_url || '',
   391	      source: normalizeSource(ev.source),
   392	      category: ev.category_slug || 'culture',
   393	      isFree: ev.is_free,
   394	      priceMin: ev.price_min_sek,
   395	      priceMax: ev.price_max_sek,
   396	      imageUrl: ev.image_url,
   397	    }));
   398	
   399	    // Collect available sources for dropdown
   400	    const availableSources = [...new Set((events || []).map(e => normalizeSource(e.source)))];
   401	    const sources = getSourcesMetadata().filter(s => availableSources.includes(s.key));
   402	
   403	    const response = {
   404	      timestamp: new Date().toISOString(),
   405	      events: transformedEvents,
   406	      sources: sources,
   407	      count: transformedEvents.length,
   408	    };
   409	
   410	    res.writeHead(200, {
   411	      'Content-Type': 'application/json',
   412	      'Access-Control-Allow-Origin': '*',
   413	    });
   414	    res.end(JSON.stringify(response));
   415	  } catch (err) {
   416	    console.error('[api] Supabase fetch error:', err);
   417	    res.writeHead(500, { 'Content-Type': 'application/json' });
   418	    res.end(JSON.stringify({ error: err.message }));
   419	  }
   420	}
